<?php
$staff=in_array(role(),['admin','pengurus'],true);
if($staff){$rows=db()->query('SELECT k.*,w.nama_lengkap,w.nik,(SELECT l.id FROM keluhan_lampiran l WHERE l.keluhan_id=k.id LIMIT 1) lampiran_id FROM keluhan_saran k JOIN data_warga w ON w.id=k.data_warga_id ORDER BY k.created_at DESC LIMIT 200')->fetchAll();}
else{$s=db()->prepare('SELECT k.*,(SELECT l.id FROM keluhan_lampiran l WHERE l.keluhan_id=k.id LIMIT 1) lampiran_id FROM keluhan_saran k WHERE k.user_id=? ORDER BY k.created_at DESC');$s->execute([user_id()]);$rows=$s->fetchAll();}
?>
<div class="page-heading"><div><h1>Keluhan & Saran</h1><p><?= $staff?'Baca, tanggapi, dan tindak lanjuti aspirasi warga.':'Sampaikan keluhan atau saran untuk perbaikan lingkungan.' ?></p></div></div>
<?php if(!$staff): ?><div class="row g-4"><div class="col-xl-5"><section class="panel-card"><div class="panel-card-header"><h2 class="panel-title">Kirim Aspirasi</h2></div><div class="panel-card-body"><form method="post" action="index.php" enctype="multipart/form-data" class="vstack gap-3" data-disable-submit><?= csrf_field() ?><input type="hidden" name="action" value="store_keluhan"><input type="hidden" name="return_page" value="keluhan"><div><label class="form-label">Jenis laporan</label><select class="form-select" name="jenis"><option value="keluhan">Keluhan</option><option value="saran">Saran</option></select></div><div><label class="form-label">Kategori</label><select class="form-select" name="kategori" required><?php foreach(['Fasilitas Lingkungan','Kebersihan','Keamanan','Pelayanan','Lainnya'] as $v): ?><option><?= e($v) ?></option><?php endforeach; ?></select></div><div><label class="form-label">Judul</label><input class="form-control" name="judul" maxlength="180" required></div><div><label class="form-label">Isi keluhan / saran</label><textarea class="form-control" name="isi" rows="5" required></textarea></div><div><label class="form-label">Lampiran foto (opsional)</label><input class="form-control" type="file" name="lampiran" accept=".pdf,.jpg,.jpeg,.png"><div class="form-text">PDF/JPG/PNG maksimal 5 MB.</div></div><button class="btn btn-army"><i class="bi bi-send me-2"></i>Kirim Laporan</button></form></div></section></div><div class="col-xl-7"><section class="panel-card h-100"><div class="panel-card-header"><h2 class="panel-title">Laporan Saya</h2><span class="text-muted-2 small"><?= count($rows) ?> laporan</span></div><div class="panel-card-body"><?php if(!$rows): ?><div class="empty-state"><i class="bi bi-chat-square-text"></i><strong>Belum ada laporan</strong><span>Laporan yang kamu kirim akan tampil di sini.</span></div><?php else: foreach($rows as $k): ?><div class="announcement-item"><div class="d-flex justify-content-between gap-2"><strong><?= e($k['judul']) ?></strong><?= status_badge($k['status']) ?></div><small class="text-muted-2"><?= e($k['nomor_laporan']) ?> · <?= e(format_date($k['created_at'])) ?></small><p class="text-muted-2 small mt-2 mb-1"><?= e($k['isi']) ?></p><?php if(!empty($k['lampiran_id'])): ?><a class="btn btn-sm btn-outline-army mt-2" href="index.php?action=download_attachment&type=keluhan&id=<?= (int)$k['lampiran_id'] ?>"><i class="bi bi-paperclip me-1"></i>Unduh lampiran</a><?php endif; ?><?php if($k['tanggapan']): ?><div class="alert alert-info mt-2 mb-0"><strong>Tanggapan:</strong> <?= e($k['tanggapan']) ?></div><?php endif; ?></div><?php endforeach; endif; ?></div></section></div></div>
<?php else: ?><section class="panel-card"><div class="data-toolbar"><span class="text-muted-2"><?= count($rows) ?> laporan warga</span><span class="ms-auto small text-muted-2">Status: Baru · Diproses · Selesai · Ditolak</span></div><div class="table-responsive"><table class="table"><thead><tr><th>Nomor</th><th>Pengirim</th><th>Judul & kategori</th><th>Jenis</th><th>Tanggal</th><th>Status</th><th>Tindak lanjut</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="7"><div class="empty-state"><i class="bi bi-chat-square-text"></i><strong>Belum ada keluhan atau saran</strong><span>Laporan yang masuk dari warga akan tampil di sini.</span></div></td></tr><?php else: foreach($rows as $k): ?><tr><td><code><?= e($k['nomor_laporan']) ?></code></td><td><strong><?= e($k['nama_lengkap']) ?></strong><small class="d-block text-muted-2"><?= e($k['nik']) ?></small></td><td><strong><?= e($k['judul']) ?></strong><small class="d-block text-muted-2"><?= e($k['kategori']) ?></small><small class="d-block text-muted-2"><?= e(mb_strimwidth($k['isi'],0,90,'…')) ?></small></td><td><?= e(ucfirst($k['jenis'])) ?></td><td><?= e(format_date($k['created_at'])) ?></td><td><?= status_badge($k['status']) ?></td><td><button class="btn btn-sm btn-outline-army" data-bs-toggle="modal" data-bs-target="#aspirasi<?= $k['id'] ?>">Tanggapi</button></td></tr><?php endforeach; endif; ?></tbody></table></div></section>
<?php foreach($rows as $k): ?><div class="modal fade" id="aspirasi<?= $k['id'] ?>" tabindex="-1"><div class="modal-dialog modal-lg modal-dialog-centered"><div class="modal-content"><div class="modal-header"><h5 class="modal-title">Detail Aspirasi Warga</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="mb-3"><div class="detail-label">Pengirim</div><div class="detail-value"><?= e($k['nama_lengkap']) ?></div></div><div class="mb-3"><div class="detail-label">Judul</div><div class="detail-value"><?= e($k['judul']) ?></div></div><div class="mb-3"><div class="detail-label">Isi</div><p class="mb-0"><?= nl2br(e($k['isi'])) ?></p><?php if(!empty($k['lampiran_id'])): ?><a class="btn btn-sm btn-outline-army mt-2" href="index.php?action=download_attachment&type=keluhan&id=<?= (int)$k['lampiran_id'] ?>">Unduh lampiran</a><?php endif; ?></div><form method="post" action="index.php" class="vstack gap-3"><?= csrf_field() ?><input type="hidden" name="action" value="update_keluhan"><input type="hidden" name="return_page" value="keluhan"><input type="hidden" name="id" value="<?= $k['id'] ?>"><div><label class="form-label">Status</label><select class="form-select" name="status"><?php foreach(['diproses'=>'Diproses','selesai'=>'Selesai','ditolak'=>'Ditolak'] as $v=>$l): ?><option value="<?= $v ?>" <?= $k['status']===$v?'selected':'' ?>><?= $l ?></option><?php endforeach; ?></select></div><div><label class="form-label">Tanggapan untuk warga</label><textarea class="form-control" name="tanggapan" rows="3"><?= e($k['tanggapan']??'') ?></textarea></div><div class="text-end"><button class="btn btn-army">Simpan Tanggapan</button></div></form></div></div></div></div><?php endforeach; ?>
<?php endif; ?>
